--!strict
local Players=game:GetService("Players");local TweenService=game:GetService("TweenService");local RunService=game:GetService("RunService");local Config=require(game:GetService("ReplicatedStorage").Modules.PuzzleConfig);local Registry=require(script.Parent.ConnectionRegistry);local Race=require(script.Parent.RaceService);local remotes=require(script.Parent.RemoteService).Ensure();local Service={};local states:{[string]:any}={}
local function player(hit:BasePart):Player?local n:Instance?=hit;while n and n~=workspace do if n:IsA("Model")and n:FindFirstChildOfClass("Humanoid")then return Players:GetPlayerFromCharacter(n)end;n=n.Parent end;return nil end
local function open(door:BasePart?)if door then door.CanCollide=false;door.Transparency=.72 end end
function Service.Bind(matchId:string,map:Folder)
	local puzzles=map:FindFirstChild("Puzzles");if not puzzles then return end;local owner="Puzzle:"..matchId;local state={players={},pushComplete=false,levers={},tweens={}};states[matchId]=state
	local colorDoor=puzzles:FindFirstChild("ColorDoor")::BasePart?
	for _,button in puzzles:GetChildren()do if button:IsA("BasePart")and button:GetAttribute("PuzzleId")=="ColorDoor"and button:GetAttribute("Step")then Registry.Register(button.Touched:Connect(function(hit)local p=player(hit);if not p then return end;local s=state.players[p]or{step=1,started=os.clock(),completed=false};state.players[p]=s;if s.completed then return end;if button:GetAttribute("Step")==Config.WorkshopColorSequence[s.step]then s.step+=1;if s.step>#Config.WorkshopColorSequence then s.completed=true;open(colorDoor);remotes.PuzzleMessage:FireClient(p,"顏色順序正確！")end else s.step=1;remotes.PuzzleMessage:FireClient(p,"順序錯誤，重新開始")end end),owner,"Touched")end end
	local box=puzzles:FindFirstChild("PushBox")::BasePart?;local plate=puzzles:FindFirstChild("PressurePlate")::BasePart?;local pushDoor=puzzles:FindFirstChild("PushDoor")::BasePart?;if box and plate then local origin=box.CFrame;Registry.Register(plate.Touched:Connect(function(hit)if hit==box then state.pushComplete=true;open(pushDoor)end end),owner,"Touched");local reset=puzzles:FindFirstChild("ResetPushBox");local prompt=reset and reset:FindFirstChildOfClass("ProximityPrompt");if prompt then Registry.Register(prompt.Triggered:Connect(function(p)local data=Race.Get(p);if state.pushComplete or Race.State~="Racing"or not data or not data.IsRacing then return end;box.CFrame=origin;box.AssemblyLinearVelocity=Vector3.zero;box.AssemblyAngularVelocity=Vector3.zero;remotes.PuzzleMessage:FireClient(p,"木箱已重置")end),owner,"Prompt")end;Registry.Register(RunService.Heartbeat:Connect(function()if not box.Parent then return end;if (box.Position-origin.Position).Magnitude>35 or box.Position.Y<0 then box.CFrame=origin;box.AssemblyLinearVelocity=Vector3.zero;box.AssemblyAngularVelocity=Vector3.zero end end),owner,"Heartbeat")end
