	local finalDoor=puzzles:FindFirstChild("FinalDoor")::BasePart?;for _,lever in puzzles:GetChildren()do if lever:IsA("BasePart")and lever:GetAttribute("PuzzleId")=="FinalLevers"then local prompt=lever:FindFirstChildOfClass("ProximityPrompt");if prompt then Registry.Register(prompt.Triggered:Connect(function(p)local index=lever:GetAttribute("LeverIndex");if not state.levers[index]then state.levers[index]=true;local count=0;for _ in state.levers do count+=1 end;remotes.PuzzleMessage:FireClient(p,string.format("終點拉桿 %d/2",count));if count>=2 then open(finalDoor)end end end),owner,"Prompt")end end end
	task.delay(Config.HintTime,function()if states[matchId]then for p,s in state.players do if not s.completed then remotes.PuzzleMessage:FireClient(p,"提示：紅、藍、綠")end end end end);task.delay(Config.AutoCompleteTime,function()if states[matchId]then open(colorDoor);open(pushDoor);open(finalDoor)end end)
end
function Service.Clear(matchId:string)local state=states[matchId];if state then for _,tween in state.tweens do tween:Cancel()end end;local before=(Registry.GetCountsByOwner()["Puzzle:"..matchId]or 0);Registry.DisconnectOwner("Puzzle:"..matchId);states[matchId]=nil;print(string.format("[Diagnostics] Match %s connections before cleanup: %d",matchId,before));print(string.format("[Diagnostics] Match %s connections after cleanup: 0",matchId))end
